"""Convert to a "stepped" data format by duplicating all but the last elt.

    Step goes up, rather than to the right.
    """
def convertToStepUpCDF(x: Any, y: Any) -> object {
    newx = [];
    newy = [];
    for (i, d) in enumerate(x) {
        newx.append(d);
        newy.append(y[i]);
        if (i != (len(x) - 1)) {
            newx.append(x[i]);
            newy.append(y[(i + 1)]);
        }
    }
    newx.append(newx[-1]);
    newy.append(1.0);
    return (newx, newy);
}
